using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioScrollbarEndsValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static MashBoxStudioViewport view;static StudioModelEditor editor;static StudioModelDocument doc;static int checks,stage;static double next;static string report;static bool pending=true;static float previousSize;
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);checks++;}
 static object Get(string n)=>typeof(StudioModelEditor).GetField(n,F).GetValue(editor);
 static void Call(string n,params object[] args)=>typeof(StudioModelEditor).GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==args.Length).Invoke(editor,args);
 public static void Run(){EditorApplication.delayCall+=Start;}
 static void Start(){report=Path.GetFullPath(Path.Combine(Application.dataPath,"../../scrollbar-ends-result.txt"));try{Check(Shader.Find("Hidden/MashBox/GizmoAntialias")&&!ShaderUtil.ShaderHasError(Shader.Find("Hidden/MashBox/GizmoAntialias")),"AA shader compilation");var icon=(Texture2D)typeof(StudioModelEditor).GetProperty("AnchorIcon",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../anchor-hierarchy-icon.png")),icon.EncodeToPNG());previousSize=StudioSettings.Current.handleSize;StudioSettings.Current.handleSize=1;doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(new StudioModelDocument.Node{name="Stem_Anchor",anchorType="Stem_Anchor"});editor=new StudioModelEditor(()=>{});editor.Load(doc);editor.SelectObject(0);view=ScriptableObject.CreateInstance<MashBoxStudioViewport>();view.position=new Rect(80,80,700,600);view.Bind(editor.Scene);view.Show();view.LookAtDirect(Vector3.zero,Quaternion.Euler(25,35,0),3);SceneView.duringSceneGui+=Draw;next=EditorApplication.timeSinceStartup+1;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}}
 static Color32[] Pixels(RenderTexture rt){var texture=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false,true);try{texture.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);texture.Apply();return texture.GetPixels32();}finally{Object.DestroyImmediate(texture);}}
 static void Save(Color32[] p,string name){var t=new Texture2D(700,600,TextureFormat.RGBA32,false,true);t.SetPixels32(p);t.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../gizmo-aa-"+name+".png")),t.EncodeToPNG());Object.DestroyImmediate(t);}
 static Vector2 Center(Color32[] p){double mass=0,x=0,y=0;for(int i=0;i<p.Length;i++){mass+=p[i].a;x+=(i%700)*p[i].a;y+=(i/700)*p[i].a;}return new Vector2((float)(x/mass),(float)(y/mass));} static int Partial(Color32[] p){int max=p.Max(c=>(int)c.a);return p.Count(c=>c.a>2&&c.a<max*.9);}
 static void Draw(SceneView scene){if(!pending||scene!=view||Event.current.type!=EventType.Repaint)return;pending=false;var rt=new RenderTexture(700,600,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear);rt.Create();var old=RenderTexture.active;var oldTarget=view.camera.targetTexture;var oldRect=view.camera.pixelRect;GL.PushMatrix();try{view.camera.targetTexture=rt;view.camera.pixelRect=new Rect(0,0,700,600);Handles.SetCamera(new Rect(0,0,700,600),view.camera);RenderTexture.active=rt;GL.Clear(true,true,Color.clear);GL.LoadProjectionMatrix(view.camera.projectionMatrix);GL.modelview=view.camera.worldToCameraMatrix;
 if(stage==0){var originalTheme=StudioSettings.Current.theme;try{foreach(var palette in StudioTheme.Palettes){StudioSettings.Current.theme=palette.Id;GL.Clear(true,true,Color.clear);Handles.BeginGUI();using(StudioTheme.Scope()){Check(GUI.skin.verticalScrollbarUpButton.fixedHeight==0&&GUI.skin.verticalScrollbarDownButton.fixedHeight==0,"Vertical end reservations remain: "+palette.Id);Check(GUI.skin.horizontalScrollbarLeftButton.fixedWidth==0&&GUI.skin.horizontalScrollbarRightButton.fixedWidth==0,"Horizontal end reservations remain: "+palette.Id);GUI.VerticalScrollbar(new Rect(40,40,14,180),0,20,0,100);GUI.VerticalScrollbar(new Rect(80,40,14,180),80,20,0,100);GUI.HorizontalScrollbar(new Rect(120,40,200,14),0,20,0,100);GUI.HorizontalScrollbar(new Rect(120,80,200,14),80,20,0,100);GUI.BeginScrollView(new Rect(360,40,200,180),Vector2.zero,new Rect(0,0,600,600),true,true);GUI.EndScrollView();GUI.BeginScrollView(new Rect(360,260,200,180),new Vector2(400+GUI.skin.verticalScrollbar.fixedWidth+GUI.skin.verticalScrollbar.margin.left,420+GUI.skin.horizontalScrollbar.fixedHeight+GUI.skin.horizontalScrollbar.margin.top),new Rect(0,0,600,600),true,true);GUI.EndScrollView();}Handles.EndGUI();var pixels=Pixels(rt);Save(pixels,"scrollbar-"+palette.Id);Func<int,int,Color> at=(x,y)=>(Color)pixels[(599-y)*700+x];foreach(var pair in new[]{new[]{46,41,46,50},new[]{86,218,86,210},new[]{121,46,130,46},new[]{318,86,310,86}}){var end=at(pair[0],pair[1]);var inside=at(pair[2],pair[3]);Check(end.a>.9f&&Mathf.Abs(end.r-inside.r)+Mathf.Abs(end.g-inside.g)+Mathf.Abs(end.b-inside.b)<.05f,"Rendered thumb cut off at end: "+palette.Id+" "+string.Join(",",pair)+" "+end+" / "+inside);}if(palette.Id=="graphite"||palette.Id=="porcelain")Save(pixels,"scrollbar-"+palette.Id);}}finally{StudioSettings.Current.theme=originalTheme;}}

 }catch(Exception e){Finish(e.ToString());}finally{view.camera.targetTexture=oldTarget;view.camera.pixelRect=oldRect;Handles.SetCamera(view.camera);GL.PopMatrix();RenderTexture.active=old;Object.DestroyImmediate(rt);}}
 static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.3;try{if(pending){view.MarkDirty(MashBoxStudioViewport.DirtyState.All);view.SendEvent(new Event{type=EventType.Layout});view.SendEvent(new Event{type=EventType.Repaint});return;}if(++stage==1){Finish("PASS "+checks+" native rendered scrollbar endpoint checks");return;}if(stage==4)view.orthographic=true;pending=true;view.MarkDirty(MashBoxStudioViewport.DirtyState.All);}catch(Exception e){Finish(e.ToString());}}
 static void Finish(string result){EditorApplication.update-=Tick;SceneView.duringSceneGui-=Draw;StudioSettings.Current.handleSize=previousSize;File.WriteAllText(report,result);bool success=result.StartsWith("PASS");EditorApplication.delayCall+=()=>{if(view)view.Close();editor?.Dispose();if(doc)Object.DestroyImmediate(doc);EditorApplication.Exit(success?0:1);};}
}
